        lines = []
        while len(lines) < 3:
            lines.append(f.readline())
        header = [l.decode().strip() for l in lines]
        w, h = map(int, header[1].split())
        pixels_text = f.read().decode('ascii').strip().split()
        pixels = [int(p) for p in pixels_text]
        return w, h, pixels

